    /// <summary>Report all metrics and their values back to the EE.</summary>
    /// <param name="compiler">Compiler instance</param>
    public readonly void report(Compiler compiler)
    {
        JitMetadata.report(compiler, nameof(ActualCodeBytes), ActualCodeBytes);
        JitMetadata.report(compiler, nameof(AllocatedHotCodeBytes), AllocatedHotCodeBytes);
        JitMetadata.report(compiler, nameof(AllocatedColdCodeBytes), AllocatedColdCodeBytes);
