    /// <summary>Merge inlinee compiler metrics to root compiler instance</summary>
    /// <param name="inlineeCompiler">inlinee compiler instance</param>
    public readonly void mergeToRoot(Compiler inlineeCompiler)
    {
        var root = inlineeCompiler.impInlineRoot;

        root.Metrics.ActualCodeBytes += inlineeCompiler.Metrics.ActualCodeBytes;
        root.Metrics.AllocatedHotCodeBytes += inlineeCompiler.Metrics.AllocatedHotCodeBytes;
        root.Metrics.AllocatedColdCodeBytes += inlineeCompiler.Metrics.AllocatedColdCodeBytes;
        root.Metrics.ReadOnlyDataBytes += inlineeCompiler.Metrics.ReadOnlyDataBytes;
        root.Metrics.GCInfoBytes += inlineeCompiler.Metrics.GCInfoBytes;
        root.Metrics.EHClauseCount += inlineeCompiler.Metrics.EHClauseCount;
        root.Metrics.PhysicallyPromotedFields += inlineeCompiler.Metrics.PhysicallyPromotedFields;
        root.Metrics.LoopsFoundDuringOpts += inlineeCompiler.Metrics.LoopsFoundDuringOpts;
        root.Metrics.LoopsInverted += inlineeCompiler.Metrics.LoopsInverted;
        root.Metrics.LoopsCloned += inlineeCompiler.Metrics.LoopsCloned;
        root.Metrics.LoopsRejectedForInsufficientBenefit += inlineeCompiler.Metrics.LoopsRejectedForInsufficientBenefit;
        root.Metrics.LoopsUnrolled += inlineeCompiler.Metrics.LoopsUnrolled;
        root.Metrics.LoopAlignmentCandidates += inlineeCompiler.Metrics.LoopAlignmentCandidates;
        root.Metrics.LoopsAligned += inlineeCompiler.Metrics.LoopsAligned;
        root.Metrics.LoopsIVWidened += inlineeCompiler.Metrics.LoopsIVWidened;
        root.Metrics.WidenedIVs += inlineeCompiler.Metrics.WidenedIVs;
        root.Metrics.UnusedIVsRemoved += inlineeCompiler.Metrics.UnusedIVsRemoved;
        root.Metrics.LoopsMadeDownwardsCounted += inlineeCompiler.Metrics.LoopsMadeDownwardsCounted;
        root.Metrics.LoopsStrengthReduced += inlineeCompiler.Metrics.LoopsStrengthReduced;
        root.Metrics.VarsInSsa += inlineeCompiler.Metrics.VarsInSsa;
        root.Metrics.HoistedExpressions += inlineeCompiler.Metrics.HoistedExpressions;
        root.Metrics.RedundantBranchesEliminated += inlineeCompiler.Metrics.RedundantBranchesEliminated;
        root.Metrics.JumpThreadingsPerformed += inlineeCompiler.Metrics.JumpThreadingsPerformed;
        root.Metrics.CseCount += inlineeCompiler.Metrics.CseCount;
        root.Metrics.BasicBlocksAtCodegen += inlineeCompiler.Metrics.BasicBlocksAtCodegen;
        root.Metrics.PerfScore += inlineeCompiler.Metrics.PerfScore;
        root.Metrics.BytesAllocated += inlineeCompiler.Metrics.BytesAllocated;
        root.Metrics.ImporterBranchFold += inlineeCompiler.Metrics.ImporterBranchFold;
        root.Metrics.ImporterSwitchFold += inlineeCompiler.Metrics.ImporterSwitchFold;
        root.Metrics.DevirtualizedCall += inlineeCompiler.Metrics.DevirtualizedCall;
        root.Metrics.DevirtualizedCallUnboxedEntry += inlineeCompiler.Metrics.DevirtualizedCallUnboxedEntry;
        root.Metrics.GDV += inlineeCompiler.Metrics.GDV;
        root.Metrics.ClassGDV += inlineeCompiler.Metrics.ClassGDV;
        root.Metrics.MethodGDV += inlineeCompiler.Metrics.MethodGDV;
        root.Metrics.MultiGuessGDV += inlineeCompiler.Metrics.MultiGuessGDV;
        root.Metrics.ChainedGDV += inlineeCompiler.Metrics.ChainedGDV;
        root.Metrics.EnumeratorGDV += inlineeCompiler.Metrics.EnumeratorGDV;
        root.Metrics.InlinerBranchFold += inlineeCompiler.Metrics.InlinerBranchFold;
        root.Metrics.InlineAttempt += inlineeCompiler.Metrics.InlineAttempt;
        root.Metrics.InlineCount += inlineeCompiler.Metrics.InlineCount;
